import sys,json,hashlib
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]));sys.path.insert(0,str(Path(__file__).resolve().parent))
from gongbi_training.runtime import configure,LAB
configure()
import numpy as np,torch
from PIL import Image,ImageDraw,ImageFont
from guohua_objects_v3_20261116 import ROOT,OLD,ARMS,COLORS,read,sha,write,check_contract
from guohua_objects_train_20261112 import confusion
ALL=['previous']+ARMS;NAMES=['上轮扩充数据模型','本轮普通续训','本轮边界／核心约束']
def main():
 ds=read(ROOT/'dataset_manifest.json');res=read(ROOT/'results.json');p=res['protocol'];assert sha(ROOT/'dataset_manifest.json')==p['dataset_sha256'];assert sha(Path(__file__).with_name('guohua_objects_v3_20261116.py'))==p['script_sha256'];assert sha(OLD/'results.json')==p['old_result_sha256'];assert sha(OLD/'expanded_control.pt')==p['initial_sha256'];assert sha(Path(__file__).resolve().parents[1]/'gongbi_training/object_core_supervision.py')==p['loss_module_sha256']
 initial=torch.load(OLD/'expanded_control.pt',map_location='cpu',weights_only=False)['model']
 for a,h in res['checkpoint_hashes'].items():
  assert sha(ROOT/(a+'.pt'))==h;state=torch.load(ROOT/(a+'.pt'),map_location='cpu',weights_only=False)['model'];assert all(torch.equal(v,state[k]) for k,v in initial.items() if k.startswith('encoder.'))
 records=[]
 for r in ds['records']:
  if r['split'] not in ['new_test','old_named_regression']:continue
  assert sha(r['image'])==r['image_sha256'] and sha(r['target'])==r['target_sha256'];im=np.array(Image.open(r['image']).convert('RGB'));t=np.array(Image.open(r['target']));Image.fromarray(im).save(ROOT/'views'/(r['id']+'_input.jpg'),quality=92);ref=np.full_like(im,[229,223,210]);ref[t!=255]=COLORS[t[t!=255]];Image.fromarray(ref).save(ROOT/'views'/(r['id']+'_reference.png'));paths={};scores=next(x for x in res['records'] if x['id']==r['id'])['scores']
  for a in ALL:
   z=np.load(ROOT/'predictions'/(r['id']+'_'+a+'.npz'));assert np.array_equal(confusion(t,z['prediction']),np.array(scores[a]['confusion']));Image.fromarray(COLORS[z['prediction']]).save(ROOT/'views'/(r['id']+'_'+a+'.png'));paths[a]='views/'+r['id']+'_'+a+'.png'
  records.append(dict(id=r['id'],split=r['split'],work_group=r['work_group'],input='views/'+r['id']+'_input.jpg',reference='views/'+r['id']+'_reference.png',predictions=paths,scores=scores))
 Image.open(LAB/'cunfa_roles_v2_20261112/references/H_14_input.png').save(ROOT/'views/H_14_input.png');paths={}
 for a in ALL:
  z=np.load(ROOT/'predictions'/('H_14_'+a+'.npz'));Image.fromarray(COLORS[z['prediction']]).save(ROOT/'views'/('H_14_'+a+'.png'));paths[a]='views/H_14_'+a+'.png'
 h=dict(id='H_14',split='known_user_regression',work_group='previously_seen',input='views/H_14_input.png',reference=None,predictions=paths,scores=None);records.insert(0,h)
 def board(rows,name):
  b=Image.new('RGB',(1440,len(rows)*350+65),'#f4f1e8');d=ImageDraw.Draw(b);font=ImageFont.truetype('C:/Windows/Fonts/msyh.ttc',18)
  for i,r in enumerate(rows):
   for j,(path,title) in enumerate(zip([r['input']]+[r['predictions'][a] for a in ALL],['原图']+NAMES)):
    im=Image.open(ROOT/path);im.thumbnail((346,280));b.paste(im,(j*360+6,i*350+35));d.text((j*360+6,i*350+5),title,font=font,fill='#294735')
   d.text((6,i*350+320),r['id'],font=font,fill='#79523a')
  d.text((6,len(rows)*350+4),'棕=山石，绿=树木，灰蓝=其他；原始对象预测，不是线稿或皴法复刻。',font=font,fill='#79523a');b.save(ROOT/name,quality=94)
 board([h],'foliage_regression.jpg');tests=[r for r in records if r['split']=='new_test'];worst=sorted(tests,key=lambda r:r['scores']['core_balanced']['mean_iou'])[:3];board(worst,'new_test_failures.jpg')
 perwork=[]
 for g in sorted({r['work_group'] for r in tests}):
  from guohua_objects_train_20261112 import metrics
  perwork.append(dict(work_group=g,scores={a:metrics(sum(np.array(r['scores'][a]['confusion']) for r in tests if r['work_group']==g)) for a in ALL}))
 write('report_data.json',dict(records=records,aggregates=res['aggregates'],user=res['user_foliage_recall'],perwork=perwork))
 checks=check_contract();checks.update(protocol_and_checkpoint_hashes_match=True,old_results_unchanged=True,frozen_encoders_unchanged=True,raw_metrics_recomputed=True,source_reference_not_masking_output=True,no_new_independent_test=True,new_expert_labels=False,model_adopted=False,robot_connected=False);write('verification.json',checks)
 page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>树石边界与核心约束 · 2026-11-16</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f1e8;color:#294735;font:16px/1.7 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1500px;margin:auto;padding:24px}h1{font-size:29px}.note{padding:15px;background:#fff7e5;border-left:5px solid #ab713b}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.card{min-width:0;background:#fffdf8;padding:10px;border:1px solid #d9d9cf}img{display:block;max-width:100%;height:auto;margin:auto}.controls{margin:16px 0;overflow-wrap:anywhere}select{font:inherit;max-width:100%;width:650px;padding:8px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:9px;border-bottom:1px solid #ccd1c7}.warn{color:#8c5134}a{color:#236b61}@media(max-width:700px){main{padding:14px}.grid{grid-template-columns:1fr}h1{font-size:24px}}</style><main><small>2026-11-16 · 离线对照 · 未采用新模型</small><h1>树石交界待定，内部两类分别约束</h1><p class="note" id="headline"></p><p>这轮实际训练了普通续训和边界／核心约束两组。相同旧权重、原63张训练图、采样、随机种子和384步预算；没有使用上轮失败的合成线描增强。候选模型在256像素训练视图上忽略树石交界附近2像素，并对两类腐蚀内部区域追加等权损失。这是组合改动，不能将收益单独归因于其中一项。</p><p class="warn">没有新增专家参考或新独立作品测试。下列14图已在上一轮查看，本轮仅作已知作品回归；12图旧作也仅作回归。指标针对源粗对象标注，不是皴法识别率、淡线恢复率或完整笔画质量。既有绘画版本不变。</p><h2>1. 同一已知案例：树叶是否保住</h2><img src="foliage_regression.jpg"><p id="foliage"></p><p>仅有1,647像素的已知树叶核心参考，无完整对象边界真值；该案例反复查看、未进训练。不把山体色块扩大当成淡线恢复成功。</p><h2>2. 同条件回归结果</h2><div class="scroll"><table><thead><tr><th>范围</th><th>方法</th><th>平均IoU</th><th>山石IoU</th><th>树木IoU</th><th>树→石</th><th>石→树</th></tr></thead><tbody id="metrics"></tbody></table></div><p>未标像素保持255并忽略；交界待定区仅影响候选的训练损失，推理不输入任何标签，不用参考遮罩修改预测。普通续训是必要对照，不能把继续训练产生的变化都算作新约束收益。</p><h2>3. 逐张看模型直接输出</h2><div class="controls"><select id="case"></select><p id="scope"></p></div><div class="grid"><div class="card"><b>原图</b><img id="input"></div><div class="card"><b>上轮扩充数据模型</b><img id="previous"></div><div class="card"><b>本轮普通续训</b><img id="continuation_control"></div><div class="card"><b>本轮边界／核心约束</b><img id="core_balanced"></div></div><details><summary>源粗对象参考</summary><img id="reference"><p id="refnote"></p></details><p>棕=山石，绿=树木，灰蓝=其他；参考米色=未标。这是粗对象区域，不能当墨带或线稿。未标空白也可能被模型误分。</p><h2>4. 保留失败案例与作品组结果</h2><img src="new_test_failures.jpg"><p>按候选平均IoU最低的三例显示，未据此重新训练、调整阈值或挑权重。</p><div class="scroll"><table><thead><tr><th>文件名作品候选</th><th>上轮IoU</th><th>普通续训IoU</th><th>边界／核心IoU</th></tr></thead><tbody id="works"></tbody></table></div><h2>5. 本轮训练参考究竟是什么</h2><p>下图依次为训练原图、源粗区域、腐蚀内部核心、准备忽略的树石交界（粉色）。从6个训练作品组抽查边界样本，源区域仍覆盖树冠内部留白，且不等于精细叶片边界。腐蚀不能纠正区域内部错标，不能称为人工精细复核或新增真值。</p><img src="training_reference_audit.jpg"><h2>6. 阶段状态</h2><p>对象与皴法仍未通过独立验收，树木画法训练保持关闭。本轮没有新增皴法分类或完整笔触训练，没有连接机械臂。下一轮优先补可靠的树石交叠、淡山体与细枝边界，再重新冻结作品验证；同时保留淡线、树叶、双向误判检查。交叉、干笔和收笔没有新增可靠证据，继续待定。</p><p><a href="protocol.json">训练前冻结协议</a> · <a href="results.json">原始结果</a> · <a href="verification.json">验证记录</a> · <a href="training_reference_audit.json">训练参考抽查</a></p></main><script>let D;const A=['previous','continuation_control','core_balanced'],N=['上轮扩充数据','普通续训','边界／核心约束'],$=s=>document.getElementById(s),pct=x=>x===null?'无参考':(x*100).toFixed(1)+'%';function show(){let r=D.records[$('case').selectedIndex];$('input').src=r.input;for(let a of A)$(a).src=r.predictions[a];if(r.reference){$('reference').src=r.reference;$('refnote').textContent='源粗区域；米色未标，忽略。'}else{$('reference').removeAttribute('src');$('refnote').textContent='已知树叶核心，无完整对象边界。'}$('scope').textContent=r.split+' / '+r.work_group}fetch('report_data.json').then(r=>r.json()).then(d=>{D=d;for(let r of d.records){let o=document.createElement('option');o.textContent=r.id;$('case').append(o)}$('case').onchange=show;show();$('foliage').textContent='已知树叶核心召回：'+A.map((a,i)=>N[i]+' '+pct(d.user[a])).join('；');let q=d.aggregates.new_test;$('headline').textContent='已知14图回归，平均IoU：'+A.map((a,i)=>N[i]+' '+pct(q[a].mean_iou)).join('；')+'。请同时检查树→石、石→树及旧作回归；本轮未通过正式独立验收。';for(let [s,t] of [['new_test','已知14图／4作品候选组'],['old_named_regression','旧12图／1作品候选组']])for(let [i,a] of A.entries()){let v=d.aggregates[s][a],tr=document.createElement('tr');tr.innerHTML='<td>'+t+'</td><td>'+N[i]+'</td>'+[v.mean_iou,v.iou[1],v.iou[2],v.tree_as_rock_rate,v.rock_as_tree_rate].map(x=>'<td>'+pct(x)+'</td>').join('');$('metrics').append(tr)}for(let r of d.perwork){let tr=document.createElement('tr');tr.innerHTML='<td>'+r.work_group+'</td>'+A.map(a=>'<td>'+pct(r.scores[a].mean_iou)+'</td>').join('');$('works').append(tr)}window.reportReady=true});</script></html>'''
 page=page.replace('<h1>树石交界待定，内部两类分别约束</h1>','<h1>本轮约束未通过：树叶回归退步</h1><p class="note"><b>新约束没有超过上轮模型，暂不采用。</b>已知14图平均IoU从70.6%降至67.1%，已知树叶核心召回从94.0%降至44.4%。新约束只比本轮普通续训略好，不能据此宣称有效。停止继续扩大这项损失的训练预算，先补可靠边界参考。</p>')
 (ROOT/'index.html').write_text(page,encoding='utf8')
 # Reuse the existing small read-only loopback server and browser assertions.
 source=Path(__file__).with_name('serve_guohua_objects_v2_20261113.py').read_text('utf8').replace('guohua_objects_v2_20261113','guohua_objects_v3_20261116').replace("'selection_before_download.json','source_checked_cunfa_concepts.json'","'training_reference_audit.jpg','training_reference_audit.json'")
 (ROOT/'serve_report.py').write_text(source.replace("str(Path(__file__).resolve().parents[1])",repr(str(Path(__file__).resolve().parents[1]))),encoding='utf8')
 checker=Path(__file__).with_name('check_guohua_objects_v2_view_20261113.py').read_text('utf8').replace('guohua_objects_v2_20261113','guohua_objects_v3_20261116').replace("'selection_before_download.json','source_checked_cunfa_concepts.json'","'training_reference_audit.json'").replace("'expanded_control.pt','line_aware_aug.pt','../expanded_control.pt','predictions/H_14_expanded_control.npz'","'core_balanced.pt','continuation_control.pt','../core_balanced.pt','predictions/H_14_core_balanced.npz'")
 (ROOT/'check_report.py').write_text(checker.replace("str(Path(__file__).resolve().parents[1])",repr(str(Path(__file__).resolve().parents[1]))),encoding='utf8');print(json.dumps(checks),flush=True)
if __name__=='__main__':main()
